-- image-generation のテーブル定義（本番の information_schema から。テスト用。データは含まない）
CREATE TYPE generated_queue_status AS ENUM ('wait', 'generated', 'generating', 'error', 'canceled');
CREATE TYPE generated_queue_type AS ENUM ('txt2img', 'img2img', 'inpaint', 'scaleup');
CREATE TABLE generated_queues (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  user_id int4 NOT NULL,
  request_content text NOT NULL,
  request_time timestamp NOT NULL,
  image_url text,
  generation_time timestamp,
  progress float8 NOT NULL DEFAULT 0,
  status generated_queue_status NOT NULL,
  is_deleted bool NOT NULL DEFAULT false,
  error text NOT NULL DEFAULT ''::text,
  ip_address varchar,
  request_to_sd_time timestamp,
  request_origin_content text NOT NULL DEFAULT ''::text,
  thumbnail_image_url text NOT NULL DEFAULT ''::text,
  requester int4,
  priority int4 NOT NULL DEFAULT 0,
  type generated_queue_type NOT NULL DEFAULT 'txt2img'::generated_queue_type,
  rating int4 NOT NULL DEFAULT 0,
  count int4 NOT NULL DEFAULT 1,
  nanoid text NOT NULL,
  platform text NOT NULL,
  created_at timestamp NOT NULL DEFAULT now(),
  updated_at timestamp NOT NULL DEFAULT now(),
  is_canceled int2 NOT NULL DEFAULT 0,
  is_reserved bool NOT NULL DEFAULT false,
  sd int4 NOT NULL DEFAULT 0,
  is_protected bool NOT NULL DEFAULT false,
  cost int4 NOT NULL DEFAULT 100,
  uuid text NOT NULL
);
CREATE UNIQUE INDEX ON generated_queues (id);
CREATE TABLE image_generation_results (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  user_id int4 NOT NULL,
  request_content text NOT NULL,
  request_time timestamp NOT NULL,
  image_url text,
  generation_time timestamp,
  status generated_queue_status NOT NULL,
  is_deleted bool NOT NULL DEFAULT false,
  ip_address varchar,
  request_to_sd_time timestamp,
  thumbnail_image_url text NOT NULL DEFAULT ''::text,
  requester int4,
  priority int4 NOT NULL DEFAULT 0,
  type generated_queue_type NOT NULL DEFAULT 'txt2img'::generated_queue_type,
  rating int4 NOT NULL DEFAULT 0,
  nanoid text NOT NULL,
  platform text NOT NULL,
  created_at timestamp NOT NULL DEFAULT now(),
  updated_at timestamp NOT NULL DEFAULT now(),
  is_canceled int2 NOT NULL DEFAULT 0,
  is_reserved bool NOT NULL DEFAULT false,
  sd int4 NOT NULL DEFAULT 0,
  is_protected bool NOT NULL DEFAULT false,
  cost int4 NOT NULL DEFAULT 100,
  uuid text NOT NULL,
  model_name text NOT NULL DEFAULT ''::text,
  prompts text NOT NULL DEFAULT ''::text
);
CREATE UNIQUE INDEX ON image_generation_results (id);
CREATE TABLE generated_reservation_queues (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  user_id int4 NOT NULL,
  request_content text NOT NULL,
  request_origin_content text NOT NULL,
  is_deleted bool NOT NULL DEFAULT false,
  ip_address text NOT NULL DEFAULT ''::text,
  created_at timestamp NOT NULL DEFAULT now(),
  wait_seconds int4 NOT NULL DEFAULT 300,
  is_generated bool NOT NULL DEFAULT false,
  sd int4 NOT NULL DEFAULT 0,
  nanoid text NOT NULL,
  cost int4 NOT NULL DEFAULT 100
);
CREATE UNIQUE INDEX ON generated_reservation_queues (id);
